ge-g113","mage-g315"}},{b="50-60",no="Best match per slot for Fire by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g356","mage-g1","mage-g380","mage-g103","mage-g401","mage-g95","mage-g370","mage-g392","mage-g423","mage-g360","mage-g427","mage-g372","mage-g363","mage-g343","mage-g390","mage-g409","mage-g416","mage-g394"}}},title="Fire | WoW Forever Mage Field Guide",nav={{id="overview",x=S[538]},{id="journey",x=S[427]},{id="talents",x=S[362]},{id="stats",x=S[451]},{id="combat",x=S[452]},{id="macros",x=S[499]},{id="dungeons",x=S[400]},{id="professions",x=S[428]},{id="crafting",x=S[414]},{id="questgear",x=S[389]},{id=S[360],x=S[509]}},asideNote=S[52],talentString="05020520010010000055500001230133031003",ranks={{tree="Arcane",name=S[378],r=5,max=5},{tree="Arcane",name=S[380],r=2,max=2},{tree="Arcane",name=S[367],r=5,max=5},{tree="Arcane",name=S[381],r=2,max=2},{tree="Arcane",name=S[440],r=1,max=1},{tree="Arcane",name=S[410],r=1,max=3},{tree="Fire",name=S[442],r=5,max=5},{tree="Fire",name="Accelerant",r=5,max=5},{tree="Fire",name="Ignite",r=5,max=5},{tree="Fire",name="Pyroblast",r=1,max=1},{tree="Fire",name=S[379],r=2,max=2},{tree="Fire",name=S[603],r=3,max=3},{tree="Fire",name="Heating Up",r=1,max=1},{tree="Fire",name=S[391],r=3,max=3},{tree="Fire",name=S[619],r=3,max=3},{tree="Fire",name="Fire Power",r=3,max=3},{tree="Fire",name="Combustion",r=1,max=1},{tree="Frost",name="Precision",r=3,max=3}},order={{l1=10,l2=14,tree="Fire",name="Accelerant",r1=1,r2=5,max=5},{l1=15,l2=19,tree="Fire",name="Ignite",r1=1,r2=5,max=5},{l1=20,l2=20,tree="Fire",name="Pyroblast",r1=1,r2=1,max=1},{l1=21,l2=24,tree="Fire",name=S[442],r1=1,r2=4,max=5},{l1=25,l2=25,tree="Fire",name="Heating Up",r1=1,r2=1,max=1},{l1=26,l2=28,tree="Fire",name=S[603],r1=1,r2=3,max=3},{l1=29,l2=31,tree="Fire",name=S[391],r1=1,r2=3,max=3},{l1=32,l2=33,tree="Fire",name=S[379],r1=1,r2=2,max=2},{l1=34,l2=36,tree="Fire",name=S[619],r1=1,r2=3,max=3},{l1=37,l2=39,tree="Fire",name="Fire Power",r1=1,r2=3,max=3},{l1=40,l2=40,tree="Fire",name="Combustion",r1=1,r2=1,max=1},{l1=41,l2=43,tree="Frost",name="Precision",r1=1,r2=3,max=3},{l1=44,l2=44,tree="Fire",name=S[442],r1=5,r2=5,max=5},{l1=45,l2=49,tree="Arcane",name=S[378],r1=1,r2=5,max=5},{l1=50,l2=51,tree="Arcane",name=S[380],r1=1,r2=2,max=2},{l1=52,l2=56,tree="Arcane",name=S[367],r1=1,r2=5,max=5},{l1=57,l2=58,tree="Arcane",name=S[381],r1=1,r2=2,max=2},{l1=59,l2=59,tree="Arcane",name=S[440],r1=1,r2=1,max=1},{l1=60,l2=60,tree="Arcane",name=S[410],r1=1,r2=1,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[390]},{t="h1",x="Fire",sub=S[501]},{t="p",s="lede",x="Single-target PvE Fire: Fireball is your main cast, with Accelerant shortening it, Ignite, Improved Scorch and Heating Up turning it into boss damage, Combustion for burst, and Arcane support for Clearcasting, mana and Arcane Blast. Not built for PvP or AoE farming."},{t="pills",list={S[398],S[262],S[429]}},{t="anchor",id="journey"},{t="kicker",x=S[539]},{t="h2",x=S[314]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Cast faster and let Ignite burn"},{t="p",x="Accelerant reaches 5/5 by level 14 and shortens Fireball by 0.5 seconds, so Fireball is your main cast. Ignite is 5/5 by 19 and adds a burn after each Fire crit. Keep Frostbolt for control, kill one target at a time, and carry a wand for low-mana finishes."},{t="p",s="level",x="20–39 · Add Pyroblast and boss damage"},{t="p",x="Pyroblast arrives at 20 and Heating Up at 25. Improved Scorch is 3/3 by 28, Master of Elements 3/3 by 31, Improved Fire Blast 2/2 by 33, Critical Mass 3/3 by 36 and Fire Power 3/3 by 39. Read your Heating Up stacks before choosing the next cast."},{t="p",s="level",x="40–60 · Frostfire Bolt takes over"},{t="p",x="Combustion arrives at 40 for burst. Precision (41–43) adds spell hit to every school and Incineration reaches 5/5 at 44. The last sixteen points go into Arcane: Improved Channeling, Arcane Subtlety and Arcane Concentration for Clearcasting, then Missile Barrage, Arcane Blast and one point of Arcane Meditation for mana while casting. There is no Ice Barrier, Presence of Mind or Arcane Power here, so plan escapes around your baseline tools."},{t="anchor",id="talents"},{t="kicker",x=S[363]},{t="h2",x=S[398]},{t="p",x=S[38]},{t="widget",w="talents"},{t="h4",s="summary",x=S[401]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[343]},{t="p",x=S[67]},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; the Fire damage comes from long single-target casts and stacking effects, not from burst against several enemies or from controlling another player."},{t="p",s="notice",x="This is a deep Fire build: 32 Fire points with Combustion, 16 Arcane points for Clearcasting, mana regeneration and Arcane Blast, and 3 Frost points in Precision for hit. Fireball, Scorch, Fire Blast and Pyroblast carry the damage. Blast Wave, Improved Flamestrike and other area-damage talents are not taken."},{t="anchor",id="stats"},{t="kicker",x=S[453]},{t="h2",x=S[382]},{t="p",x="Fire wants spell damage and critical strike: crits build Heating Up, trigger Ignite and refund mana through Master of Elements."},{t="h3",x=S[522]},{t="stat",i=1,b=S[560],x=S[517]},{t="stat",i=2,b="Intellect",x=S[545]},{t="stat",i=3,b="Stamina",x="safer pulls"},{t="stat",i=4,b="Spirit",x=S[344]},{t="p",s="small",x="Precision gives 6% hit to all your spells, which covers enemies of your level."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[517]},{t="stat",i=3,b=S[510],x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="stat",i=6,b="Spirit",x=""},{t="p",s="small",x="With Precision you need about 11% hit from gear. Spell penetration and haste are useful extras."},{t="p",s="notice",x=S[35]},{t="anchor",id="combat"},{t="kicker",x=S[383]},{t="h2",x=S[523]},{t="p",x=S[66]},{t="h4",x="Open from range"},{t="p",x="Open with Fireball (Accelerant makes it 0.5 seconds faster at 5/5), or with Pyroblast on a target that will live long enough. Frostbolt is for establishing space when control matters more than damage. Pull one enemy at a time and finish it before looking at the next."},{t="h4",x="From 40, make Frostfire Bolt your main cast"},{t="p",x="Fireball is the spell you cast most: Accelerant shortens it by 0.5 seconds, its non-periodic crits build Heating Up, every Fire crit triggers Ignite, and Master of Elements refunds 30% of the base mana cost of Fire crits. Incineration 5/5 adds critical chance to your affected Fire spells. Arcane Concentration gives you free Clearcasting casts: spend them on Fireball or Pyroblast."},{t="h4",x="Apply Improved Scorch on durable targets"},{t="p",x="Improved Scorch is 3/3, so every Scorch applies Fire vulnerability: +3% Fire damage per stack, up to 5 stacks, lasting 30 seconds. On a boss or other long fight, build it first and keep it up; on a short quest fight it can cost more time than it saves. Fire Power rewards the Fire effects you keep on the target."},{t="h4",x="Read Heating Up before Pyroblast"},{t="p",x="Non-periodic crits from Fireball, Fire Blast and Scorch each cut the cast time of your next Pyroblast by 25%, up to 3 stacks, and Fire Blast adds an extra stack when it deals damage. Improved Fire Blast makes Fire Blast available 2 seconds sooner. Cast a shortened Pyroblast when you have a window and the target will live; three stacks reduce its cast time by 75%, not to an automatic instant cast."},{t="h4",x="Use Combustion at the start of a damage window"},{t="p",x="Activate Combustion when the target will survive your whole burst: each Fire damage hit raises your Fire crit chance by 10% until you land 3 non-periodic crits. Combine it with a Pyroblast and your Heating Up stacks, and keep Critical Mass and Fire Power in mind when you compare gear."},{t="h4",x="Treat the Frost package as support"},{t="p",x="Precision adds spell hit to every school. Improved Channeling and Arcane Concentration give you free Clearcasting casts, Missile Barrage can make Arcane Missiles free and faster, and Arcane Blast adds spell damage from your Intellect for a short burst; Arcane Meditation keeps some mana regeneration going while you cast."},{t="h4",x="Stay on single targets"},{t="p",x="This build has no Counterspell silence, Impact stun or area talents, and it is not meant for PvP or AoE farming. In groups, leave pack damage to others and keep Fireball and Pyroblast on your boss target."},{t="h4",x=S[325]},{t="p",x=S[23]},{t="abil",names={"Fireball","Frostbolt","Fire Blast","Pyroblast","Scorch","Combustion","Mana Gem"}},{t="h3",x=S[487]},{t="p",x="Compare Fire spell damage, Intellect, spell critical chance and hit. Precision is 3/3 here, giving +6% spell hit to every school, and Ignite, Master of Elements and Heating Up all reward crits. Spirit and Stamina can improve real questing uptime, and Intellect also feeds the Arcane Blast bonus."},{t="p",x=S[74]},{t="h3",x=S[374]},{t="p",x=S[24]},{t="p",x=S[42]},{t="p",x=S[57]},{t="anchor",id="macros"},{t="kicker",x=S[503]},{t="h2",x=S[280]},{t="p",x=S[45]},{t="p",s="notice",x=S[33]},{t="macro",n=S[447],x=S[146],code=S[155]},{t="macro",n=S[415],x=S[157],code=S[130]},{t="macro",n=S[402],x=S[131],code=S[111]},{t="macro",n=S[375],x=S[208],code=S[120]},{t="macro",n="Blink now",x=S[188],code=S[259]},{t="macro",n=S[524],x=S[218],code=S[213]},{t="macro",n=S[454],x=S[113],code=S[243]},{t="macro",n=S[430],x=S[179],code=S[219]},{t="macro",n=S[416],x=S[158],code=S[207]},{t="macro",n=S[561],x=S[202],code=S[326]},{t="macro",n=S[441],x=S[135],code=S[220]},{t="macro",n=S[455],x=S[180],code=S[251]},{t="p",s="small",x=S[108]},{t="anchor",id="dungeons"},{t="kicker",x=S[511]},{t="h2",x=S[345]},{t="p",x=S[39]},{t="widget",w="rarity"},{t="p",s="notice",x=S[28]},{t="p",s="notice",x=S[34]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[384]},{t="h2",x=S[341]},{t="p",x=S[41]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[403]},{t="h2",x=S[315]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[385]},{t="h2",x=S[292]},{t="p",x=S[30]},{t="widget",w="quest"},{t="anchor",id=S[360]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[54]}}},{id="frost",name="Frost",token="FROST",gearBrackets={{b="Quest rewards",no="Quest rewards that fit this spec's stat priority, sorted by quest level. The tooltip names the quest, its level, the quest giver and the faction. Quest level is not the minimum pickup level.",keys={"st-mage-2","st-mage-1","mage-g40","mage-g99","mage-g137","mage-g75","mage-g50","mage-g62","mage-g121","mage-g3","mage-g39","mage-g98","mage-g23","mage-g24","mage-g69","mage-g82","mage-g140","mage-g136","mage-g19","mage-g28","mage-g72","mage-g114","mage-g118","mage-g54","mage-g84","mage-g91","mage-g42","mage-g56","mage-g65","mage-g119","mage-g8","mage-g22","mage-g78","mage-g109","mage-g14","mage-g52","mage-g96","mage-g127","mage-g21","mage-g41","mage-g60","mage-g128","mage-g45","mage-g73","mage-g100","mage-g102","mage-g104","mage-g130","mage-g26","mage-g29","mage-g30","mage-g53","mage-g61","mage-g79","mage-g57","mage-g68","mage-g74","mage-g141","mage-g142","mage-g125","mage-g10","mage-g46","mage-g83","mage-g90","mage-g93","mage-g15","mage-g31","mage-g34","mage-g266","mage-g47","mage-g138","mage-g139","mage-g81","mage-g5","mage-g25","mage-g129","mage-g16","mage-g17","mage-g18","mage-g55","mage-g77","mage-g86","mage-g87","mage-g94","mage-g117","mage-g89","mage-g269","mage-g267","mage-g85","mage-g35","mage-g58","mage-g120","mage-g108","mage-g20","mage-g80","mage-g112","mage-g0","mage-g2","mage-g12","mage-g132","mage-g37","mage-g131","mage-g71","mage-g116","mage-g32","mage-g48","mage-g92","mage-g4","mage-g49","mage-g88","mage-g63","mage-g67","mage-g113","mage-g64","mage-g36","mage-g44","mage-g122","mage-g123","mage-g11","mage-g105","mage-g1","mage-g6","mage-g7","mage-g9","mage-g13","mage-g27","mage-g33","mage-g38","mage-g43","mage-g51","mage-g59","mage-g66","mage-g70","mage-g76","mage-g95","mage-g101","mage-g103","mage-g106","mage-g107","mage-g115","mage-g124","mage-g126","mage-g133","mage-g134","mage-g135"}},{b="1-19",no="Best match per slot for Frost by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g66","mage-g98","mage-g192","mage-g142","mage-g54","mage-g118","mage-g60","mage-g175","mage-g161","mage-g170","mage-g72","mage-g28","mage-g155","mage-g137","mage-g141"}},{b="20-29",no="Best match per slot for Frost by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g229","mage-g242","mage-g10","mage-g15","mage-g234","mage-g241","mage-g196","mage-g127","mage-g204","mage-g194","mage-g83","mage-g93","mage-g208","mage-g193","mage-g224","mage-g31"}},{b="30-39",no="Best match per slot for Frost by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g282","mage-g58","mage-g244","mage-g256","mage-g259","mage-g5","mage-g279","mage-g270","mage-g280","mage-g129","mage-g90","mage-g267","mage-g261","mage-g17","mage-g286"}},{b="40-49",no="Best match per slot for Frost by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g301","mage-g71","mage-g320","mage-g323","mage-g288","mage-g36","mage-g310","mage-g311","mage-g290","mage-g43","mage-g336","mage-g308","mage-g333","mage-g113","mage-g315"}},{b="50-60",no="Best match per slot for Frost by stat priority, picked from dungeon drops, quest rewards and crafting at this level range. Quest and crafted pieces are listed in the sections below.",keys={"mage-g356","mage-g1","mage-g380","mage-g103","mage-g401","mage-g95","mage-g370","mage-g392","mage-g423","mage-g360","mage-g427","mage-g372","mage-g363","mage-g343","mage-g390","mage-g409","mage-g416","mage-g394"}}},title="Frost | WoW Forever Mage Field Guide",nav={{id="overview",x=S[538]},{id="journey",x=S[427]},{id="talents",x=S[362]},{id="stats",x=S[451]},{id="combat",x=S[452]},{id="macros",x=S[499]},{id="dungeons",x=S[400]},{id="professions",x=S[428]},{id="crafting",x=S[414]},{id="questgear",x=S[389]},{id=S[360],x=S[509]}},asideNote=S[52],talentString="00000000000000000015520001200130000203501330101301251",ranks={{tree="Fire",name=S[442],r=1,max=5},{tree="Fire",name="Accelerant",r=5,max=5},{tree="Fire",name="Ignite",r=5,max=5},{tree="Fire",name=S[613],r=2,max=2},{tree="Fire",name="Pyroblast",r=1,max=1},{tree="Fire",name=S[379],r=2,max=2},{tree="Fire",name="Heating Up",r=1,max=1},{tree="Fire",name=S[391],r=3,max=3},{tree="Frost",name=S[620],r=2,max=2},{tree="Frost",name="Precision",r=3,max=3},{tree="Frost",name="Ice Shards",r=5,max=5},{tree="Frost",name=S[546],r=1,max=2},{tree="Frost",name="Permafrost",r=3,max=3},{tree="Frost",name=S[504],r=3,max=3},{tree="Frost",name="Ice Lance",r=1,max=1},{tree="Frost",name="Ice Block",r=1,max=1},{tree="Frost",name="Shatter",r=3,max=3},{tree="Frost",name="Cold Snap",r=1,max=1},{tree="Frost",name=S[594],r=2,max=2},{tree="Frost",name=S[614],r=5,max=5},{tree="Frost",name="Ice Barrier",r=1,max=1}},order={{l1=10,l2=12,tree="Frost",name="Precision",r1=1,r2=3,max=3},{l1=13,l2=14,tree="Frost",name=S[620],r1=1,r2=2,max=2},{l1=15,l2=19,tree="Frost",name="Ice Shards",r1=1,r2=5,max=5},{l1=20,l2=20,tree="Frost",name="Ice Lance",r1=1,r2=1,max=1},{l1=21,l2=22,tree="Frost",name=S[504],r1=1,r2=2,max=3},{l1=23,l2=24,tree="Frost",name="Permafrost",r1=1,r2=2,max=3},{l1=25,l2=25,tree="Frost",name="Ice Block",r1=1,r2=1,max=1},{l1=26,l2=26,tree="Frost",name="Permafrost",r1=3,r2=3,max=3},{l1=27,l2=29,tree="Frost",name="Shatter",r1=1,r2=3,max=3},{l1=30,l2=30,tree="Frost",name="Cold Snap",r1=1,r2=1,max=1},{l1=31,l2=32,tree="Frost",name=S[594],r1=1,r2=2,max=2},{l1=33,l2=33,tree="Frost",name=S[546],r1=1,r2=1,max=2},{l1=34,l2=34,tree="Frost",name=S[504],r1=3,r2=3,max=3},{l1=35,l2=39,tree="Frost",name=S[614],r1=1,r2=5,max=5},{l1=40,l2=40,tree="Frost",name="Ice Barrier",r1=1,r2=1,max=1},{l1=41,l2=45,tree="Fire",name="Accelerant",r1=1,r2=5,max=5},{l1=46,l2=50,tree="Fire",name="Ignite",r1=1,r2=5,max=5},{l1=51,l2=51,tree="Fire",name=S[442],r1=1,r2=1,max=5},{l1=52,l2=53,tree="Fire",name=S[613],r1=1,r2=2,max=2},{l1=54,l2=54,tree="Fire",name="Pyroblast",r1=1,r2=1,max=1},{l1=55,l2=56,tree="Fire",name=S[379],r1=1,r2=2,max=2},{l1=57,l2=57,tree="Fire",name="Heating Up",r1=1,r2=1,max=1},{l1=58,l2=60,tree="Fire",name=S[391],r1=1,r2=3,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[390]},{t="h1",x="Frost",sub=S[501]},{t="p",s="lede",x="Single-target PvE Frost built around Frostfire Bolt from level 40: Frostbolt and Ice Lance before that, Fingers of Frost and Winter's Chill to line up burst, and Ice Barrier for extra Frost damage and uninterrupted casting. Not built for PvP or AoE farming."},{t="pills",list={S[399],S[262],S[429]}},{t="anchor",id="journey"},{t="kicker",x=S[539]},{t="h2",x=S[314]},{t="p",x=S[49]},{t="p",s="level",x="1–19 · Cast faster and hit more often"},{t="p",x="Precision 3/3 by level 12 adds spell hit, Frost Warding 2/2 by 14 strengthens your Frost Ward and Ice Barrier, and Ice Shards 5/5 by 19 makes Frost crits hit harder. Keep room behind you before starting a pull, Polymorph separates an extra enemy, and Frost Nova creates space but damage can break the root. Maintain your trained spell ranks."},{t="p",s="level",x="20–39 · Develop frozen-target damage"},{t="p",x="Ice Lance arrives at 20, then Frost Channeling, Permafrost, Ice Block at 25 and Shatter by 29. Cold Snap arrives at 30, Fingers of Frost at 31–32, one point of Improved Frost Nova at 33 and Winter's Chill by 39. A Fingers proc grants a damage condition; it does not physically root the target."},{t="p",s="level",x="40–60 · Ice Barrier, then Fire and Arcane support"},{t="p",x="Ice Barrier at 40 completes the Frost tree, and Frostfire Bolt, trained at 40, becomes your main cast. The last twenty points all go into Fire to strengthen it: Accelerant and Ignite (41–50), then Incineration, Flame Throwing, Pyroblast, Improved Fire Blast, Heating Up and Master of Elements (51–60). This route has no Improved Blizzard, Improved Cone of Cold or Arcane talents."},{t="anchor",id="talents"},{t="kicker",x=S[363]},{t="h2",x=S[399]},{t="p",x=S[38]},{t="widget",w="talents"},{t="h4",s="summary",x=S[401]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[343]},{t="p",x=S[67]},{t="widget",w="order"},{t="p",s="notice",x="|cffffffffBuilt for single-target PvE.|r This allocation is tuned for one enemy at a time: questing elites, dungeon bosses and raid-style boss fights. It is not a PvP build and not an area-damage (AoE) farming build; this route buys no Improved Blizzard or Improved Cone of Cold, and the Frost control tools are only the baseline ones plus Permafrost."},{t="p",s="notice",x="The 0/20/31 split keeps the Frost tree for single-target output and protection and spends the rest in Fire to support Frostfire Bolt, which counts as both Fire and Frost. Ice Barrier is both protection and a Frost damage buff. Accelerant, Ignite, Heating Up and Master of Elements pay off through Frostfire Bolt and Pyroblast. One point of Improved Frost Nova is the only extra control talent."},{t="anchor",id="stats"},{t="kicker",x=S[453]},{t="h2",x=S[382]},{t="p",x="Frost wants spell damage and critical strike. Ice Shards adds extra crit damage to Frost spells, so crit is worth more here than in Classic."},{t="h3",x=S[522]},{t="stat",i=1,b=S[560],x=S[507]},{t="stat",i=2,b="Intellect",x=S[545]},{t="stat",i=3,b="Stamina",x="safer pulls"},{t="stat",i=4,b="Spirit",x=S[344]},{t="p",s="small",x="Mana limits how fast you level, so do not ignore Spirit: finish enemies with your wand to let Spirit regeneration restart sooner."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[507]},{t="stat",i=3,b=S[510],x=""},{t="stat",i=4,b="Intellect",x=""},{t="stat",i=5,b="Mana per 5",x=""},{t="stat",i=6,b="Spirit",x=""},{t="p",s="small",x="Talents give 5–6% hit, so you need about 11–12% from gear. Frost damage items usually carry more of it than plain spell power, and Frost damage counts equally."},{t="p",s="notice",x=S[35]},{t="anchor",id="combat"},{t="kicker",x=S[383]},{t="h2",x=S[523]},{t="p",x=S[66]},{t="h4",x="Prepare range and protection"},{t="p",x="Apply Arcane Intellect, choose an armor spell, and from 40 cast Ice Barrier before the fight: it absorbs 448 damage, raises your Frost damage by 15% for a minute, adds a further 5% while it is up, and stops damage from costing you cast time. Open with Frostbolt from a position that allows retreat, and recast the barrier when it falls off."},{t="h4",x="Let Frostbolt do the steady work"},{t="p",x="Frostbolt is your core cast until 40, and Frostfire Bolt takes over from 40. Frost Channeling cuts the mana cost of Frost spells by 10%, Precision adds 6% hit to all spells, and Ice Shards doubles the extra damage of Frost crits (+100%). Permafrost lengthens your Chill effects by 33% and slows by a further 10%."},{t="h4",x="Use the frozen opportunity"},{t="p",x="Ice Lance has an 8-second cooldown shared with Fire Blast. Ice Lance deals 300% increased damage to Frozen targets and Shatter adds up to 50% crit chance against them. Fingers of Frost at 2/2 treats your next 2 spells as if the target were Frozen for 15 seconds, so fire Ice Lance while it is active. Remember that a slow is not a freeze, and a freeze-immune boss ignores all of it."},{t="h4",x="Build and spend Winter's Chill safely"},{t="p",x="Frostbolt and Fingers-empowered Ice Lance each have a 100% chance to apply a stack. Each stack raises the damage of your next Cone of Cold by 20% and adds a further 7% of your spell damage, up to 5 stacks. Build the stacks on one target, then spend them with a single Cone of Cold as a burst finisher; do not move into lethal damage just to cash in."},{t="h4",x="Use Frostfire Bolt and the support points"},{t="p",x="Accelerant (0.5 seconds off the cast) and Ignite (a burn after each Fire crit) only help Fire-school casts, so from 40 they make Frostfire Bolt your faster main cast; its crits also build Heating Up for a shortened Pyroblast, and Master of Elements refunds mana on Fire and Frost crits. Frostfire Bolt is not among the spells that apply Winter's Chill, so weave Frostbolt and Ice Lance when you want stacks for Cone of Cold."},{t="h4",x="Plan cooldowns around the fight"},{t="p",x="Ice Block buys emergency time but you cannot attack while in it. Cold Snap resets your other Frost cooldowns, including Ice Block. Plan the follow-up action so you do not end Ice Block surrounded and out of space."},{t="h4",x="Treat AoE and PvP as separate plans"},{t="p",x="This build targets controlled questing and dungeon single-target work. Blizzard and Cone of Cold work as a plain spell, but their talented bonuses are not here, and the build has no Frostbite or Improved Frost Nova. Do not copy a large-pack farming or PvP route that assumes a different allocation."},{t="h4",x=S[325]},{t="p",x=S[23]},{t="abil",names={"Frostbolt","Frostfire Bolt","Ice Lance","Cone of Cold","Ice Barrier","Cold Snap","Mana Gem"}},{t="h3",x=S[487]},{t="p",x="Compare Frost or general spell damage, Intellect, useful spell hit and critical chance, with Stamina and Spirit for survival and recovery. Precision is 3/3 in this build (+6% hit), and Ice Shards makes each Frost crit hit much harder, so critical chance is worth more here than on a build without it. A slow is not a freeze, and a freeze-immune boss does not become rooted because Fingers of Frost activated. Wands remain useful low-mana tools, but their weapon DPS is not a Frostbolt stat."},{t="p",x=S[74]},{t="h3",x=S[374]},{t="p",x=S[24]},{t="p",x=S[42]},{t="p",x=S[57]},{t="anchor",id="macros"},{t="kicker",x=S[503]},{t="h2",x=S[280]},{t="p",x=S[45]},{t="p",s="notice",x=S[33]},{t="macro",n=S[447],x=S[146],code=S[155]},{t="macro",n=S[415],x=S[157],code=S[130]},{t="macro",n=S[402],x=S[131],code=S[111]},{t="macro",n=S[375],x=S[208],code=S[120]},{t="macro",n="Blink now",x=S[188],code=S[259]},{t="macro",n=S[524],x=S[218],code=S[213]},{t="macro",n=S[454],x=S[113],code=S[243]},{t="macro",n=S[430],x=S[179],code=S[219]},{t="macro",n=S[416],x=S[158],code=S[207]},{t="macro",n=S[561],x=S[202],code=S[326]},{t="macro",n=S[441],x=S[135],code=S[220]},{t="macro",n=S[455],x=S[180],code=S[251]},{t="p",s="small",x=S[108]},{t="anchor",id="dungeons"},{t="kicker",x=S[511]},{t="h2",x=S[345]},{t="p",x=S[39]},{t="widget",w="rarity"},{t="p",s="notice",x=S[28]},{t="p",s="notice",x=S[34]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[384]},{t="h2",x=S[341]},{t="p",x=S[41]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[403]},{t="h2",x=S[315]},{t="p",x=S[37]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[385]},{t="h2",x=S[292]},{t="p",x=S[30]},{t="widget",w="quest"},{t="anchor",id=S[360]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[54]}}}},dungeons={{n=S[356],lr="13–18",st=S[83],no=S[14],ba=true,ra={ck=S[139],r={},t={},no={S[36],S[47],"Dungeon availability is confirmed separately from individual drop assignments. https://foreverchanges.pro/dungeons/ragefire-chasm"}}},{n=S[237],lr="13–18",st=S[83],no=S[14],ba=true,ra={ck=S[139],r={},t={},no={S[36],S[47],"Dungeon availability is confirmed separately from individual drop assignments. https://foreverchanges.pro/dungeons/hall-of-thanes"}}},{n=S[201],lr="15–